content.text:
"actions": [
  {
    "action": "send-email",
    "recipients": [
      "@Approvers Business@",
      "user1"
    ],
    "notification": {
      "subject": "${content.title} is In Approval State",
      "title": "${content.title} is In Approval State",
      "body": "Hello @Approvers QA@, this document in approval state and needs to be reviewed"
    }

"triggers":
[
	{"event": "on-approval-unassigned",
	"conditions":
	[
		{"state":"Review"}
	],
	"actions":[       
	       {"action": "set-message",
            "type": "warning",
            "title": "Reviewer has been unassigned",
            "body": "A new reviewer may need to be assigned"
           }]
     }
]

"triggers":
[
	{"event": "on-approval-assigned",
	"conditions":
	[
		{"state":"Review"}
	],
	"actions":
	[   
			{"action": "send-email",
            "recipients":
            [
                "@creator",
                "@watchers",
                "@lastUpdatedBy",
            ],
            "notification": {"subject": "${content.title} has been assigned in the Review state",
                "title": "${content.title} is assigned",
                "body": "Hello, ${content.link} in the ${content.space} space is
                in approval state Review and has been assigned"}}
    ]}
]

"triggers":
[
	{"event": "on-change-state",
	"conditions":
	[
		{"state":"Expired"}
	],
	"actions":
	[
		{"action": "set-message",
			"type": "info",
			"title": "Stale content",
			"body": "Content may be out of date"}
	]}
]
